-- Fill in the Pudu delivery robots' product pages (Admin -> Products) with
-- the full-screen design: header cut-out, four key figures, photo sections,
-- the spec table and FAQs. One update per robot:
--   pudu-bella -> BellaBot
--   pudu-2     -> PuduBot 2
--
-- Facts come from Pudu's product pages (pudurobotics.com/en/products/...).
-- Photos are Pudu's shots with the Pudu marks and award badges painted out
-- (public/models/pudu/<robot>/); the headers are the logo-free cut-outs on S3.
-- The Thai text is a DRAFT for the Thai team.
--
-- Renames each product and sets its photo, texts and page. Leaves alone:
-- price, visible, conditions (how it is sold), the recommender facts (fit)
-- and the order. Safe to run before the new code is live: the rows stay
-- hidden until Visible is ticked in Admin. Safe to re-run.
--
-- Run in Supabase: SQL Editor -> New query -> paste -> Run. Nothing to edit.

begin;

-- BellaBot
update public.products set
  name = 'BellaBot',
  brand = 'Pudu',
  category = 'delivery-robots',
  image_url = 'https://d5hk9n8my7l32.cloudfront.net/Pudu/BellaBot/BellaBot-cutout.webp',
  tagline = '{"en":"A cat-faced delivery robot that carries four trays to the table and charms guests on the way.","th":"หุ่นยนต์เสิร์ฟอาหารหน้าแมว ส่งอาหาร 4 ถาดถึงโต๊ะ พร้อมสร้างรอยยิ้มให้ลูกค้าระหว่างทาง"}'::jsonb,
  description = '{"en":"Pudu BellaBot delivery robot in Thailand: 4 trays and up to 40 kg per trip, 13 h battery life, laser and camera navigation, 3D obstacle avoidance. Get a quote from FindMyRobo.","th":"หุ่นยนต์เสิร์ฟอาหาร Pudu BellaBot ในประเทศไทย 4 ถาด รับน้ำหนักได้ถึง 40 กก. ต่อรอบ แบตเตอรี่ใช้งานได้ 13 ชม. นำทางด้วยเลเซอร์และกล้อง หลบสิ่งกีดขวางแบบ 3 มิติ ขอใบเสนอราคาจาก FindMyRobo"}'::jsonb,
  features = '{"en":["Max load: 40 kg (4 trays)","Battery life: 13 h (no load)","Speed: 0.5–1.2 m/s","Obstacle sensing: 3 RGBD cameras + LiDAR"],"th":["รับน้ำหนักสูงสุด: 40 กก. (4 ถาด)","แบตเตอรี่ใช้งานได้: 13 ชม. (ไม่มีน้ำหนักบรรทุก)","ความเร็ว: 0.5–1.2 ม./วินาที","ตรวจจับสิ่งกีดขวาง: กล้อง RGBD 3 ตัว + LiDAR"]}'::jsonb,
  page = '{"showcase":{"eyebrow":{"en":"Pudu · Delivery robot for restaurants and retail","th":"Pudu · หุ่นยนต์เสิร์ฟอาหารสำหรับร้านอาหารและร้านค้า"},"heroImage":"https://d5hk9n8my7l32.cloudfront.net/Pudu/BellaBot/BellaBot-cutout.webp","figures":[{"value":"4","label":{"en":"Trays","th":"ถาด"}},{"value":"40 kg","label":{"en":"Max load, 10 kg per tray","th":"รับน้ำหนักสูงสุด ถาดละ 10 กก."}},{"value":"13 h","label":{"en":"Battery life, no load","th":"แบตเตอรี่ ไม่มีน้ำหนักบรรทุก"}},{"value":"0.5–1.2 m/s","label":{"en":"Speed, adjustable","th":"ความเร็ว ปรับได้"}}]},"blocks":[{"type":"feature","eyebrow":{"en":"Navigation","th":"การนำทาง"},"heading":{"en":"Finds its own way.","th":"หาทางไปเองได้"},"body":{"en":"BellaBot navigates by laser (LiDAR) or by camera (visual SLAM), so it suits more kinds of venue. Laser positioning needs no markers and works under any ceiling height; marker positioning works with ceilings up to 8 m.","th":"BellaBot นำทางได้ทั้งด้วยเลเซอร์ (LiDAR) และด้วยกล้อง (Visual SLAM) จึงใช้งานได้ในสถานที่หลากหลายกว่า การระบุตำแหน่งด้วยเลเซอร์ไม่ต้องติดมาร์กเกอร์และไม่จำกัดความสูงเพดาน ส่วนแบบใช้มาร์กเกอร์รองรับเพดานสูงได้ถึง 8 เมตร"},"image":"/models/pudu/bellabot/navigation.webp"},{"type":"feature","eyebrow":{"en":"Safety","th":"ความปลอดภัย"},"heading":{"en":"Sees obstacles in 3D.","th":"มองเห็นสิ่งกีดขวางแบบ 3 มิติ"},"body":{"en":"Three RGBD depth cameras work with the LiDAR to spot obstacles from any angle, including low ones and ones that hang over its path. It stops in as little as 0.5 seconds, then moves on around them.","th":"กล้องวัดความลึก RGBD 3 ตัวทำงานร่วมกับ LiDAR ตรวจจับสิ่งกีดขวางได้จากทุกมุม ทั้งสิ่งที่อยู่ต่ำและสิ่งที่ยื่นลงมาขวางทาง หยุดได้เร็วสุดภายใน 0.5 วินาที แล้วเลี่ยงไปต่อ"},"image":"/models/pudu/bellabot/sensors.webp"},{"type":"feature","eyebrow":{"en":"Guests","th":"ลูกค้า"},"heading":{"en":"A cat people come back to see.","th":"แมวที่ลูกค้าอยากกลับมาเจออีก"},"body":{"en":"Dozens of original cat expressions on its face, voice greetings, lights that show what it is doing, and a response when it is touched. BellaBot is built to bring guests a little delight with every delivery.","th":"ใบหน้าแสดงอารมณ์แมวได้หลายสิบแบบ มีเสียงทักทาย ไฟบอกสถานะการทำงาน และตอบสนองเมื่อถูกสัมผัส BellaBot ถูกออกแบบมาเพื่อสร้างความประทับใจเล็ก ๆ ให้ลูกค้าในทุกการเสิร์ฟ"},"image":"/models/pudu/bellabot/guests.webp"},{"type":"feature","eyebrow":{"en":"Trays","th":"ถาด"},"heading":{"en":"Four trays, 40 kg a trip.","th":"4 ถาด 40 กก. ต่อรอบ"},"body":{"en":"Each 41 × 50 cm tray holds up to 10 kg. An infrared sensor watches the trays, and the trays come off quickly for cleaning.","th":"ถาดขนาด 41 × 50 ซม. รับน้ำหนักได้ถาดละ 10 กก. มีเซนเซอร์อินฟราเรดตรวจจับถาด และถอดถาดออกมาทำความสะอาดได้ง่าย"},"image":"/models/pudu/bellabot/trays.webp"},{"type":"feature","eyebrow":{"en":"Ride","th":"การเคลื่อนที่"},"heading":{"en":"Soup stays in the bowl.","th":"ซุปไม่หกจากชาม"},"body":{"en":"Automotive-grade independent suspension adjusts its damping to the floor, keeping the trays steady on the way to the table. It handles slopes of up to 5°.","th":"ระบบกันสะเทือนอิสระระดับยานยนต์ปรับความหน่วงตามสภาพพื้น ช่วยให้ถาดนิ่งตลอดทางไปถึงโต๊ะ และขึ้นทางลาดได้สูงสุด 5°"},"image":"/models/pudu/bellabot/suspension.webp"},{"type":"feature","eyebrow":{"en":"Battery","th":"แบตเตอรี่"},"heading":{"en":"Swap the battery, keep serving.","th":"เปลี่ยนแบตเตอรี่ แล้วเสิร์ฟต่อได้ทันที"},"body":{"en":"Up to 13 hours on a charge without a load, and 4.5 hours to recharge. The battery swaps out quickly, so BellaBot can keep working through long days.","th":"ใช้งานได้สูงสุด 13 ชั่วโมงต่อการชาร์จเมื่อไม่มีน้ำหนักบรรทุก ชาร์จเต็มใน 4.5 ชั่วโมง และเปลี่ยนแบตเตอรี่ได้รวดเร็ว BellaBot จึงทำงานต่อเนื่องได้ตลอดวันที่ยาวนาน"},"image":"/models/pudu/bellabot/battery.webp"},{"type":"feature","eyebrow":{"en":"Calling","th":"การเรียกใช้งาน"},"heading":{"en":"Call it from anywhere.","th":"เรียกใช้งานได้จากทุกที่"},"body":{"en":"Staff can call and manage BellaBot from the PUDU Link app, a push-button caller or a 4G watch. The app also shows each robot''s status and operating data. Calling devices are optional: ask us what is included.","th":"พนักงานเรียกและจัดการ BellaBot ได้ผ่านแอป PUDU Link ปุ่มกดเรียก หรือนาฬิกา 4G แอปยังแสดงสถานะและข้อมูลการทำงานของหุ่นยนต์แต่ละตัว อุปกรณ์เรียกเป็นตัวเลือกเสริม สอบถามเราได้ว่ามีอะไรรวมอยู่บ้าง"}}],"specGroups":[{"title":{"en":"Trays and load","th":"ถาดและน้ำหนักบรรทุก"},"rows":[{"label":{"en":"Trays","th":"จำนวนถาด"},"value":{"en":"4","th":"4 ถาด"}},{"label":{"en":"Max load","th":"รับน้ำหนักสูงสุด"},"value":{"en":"40 kg, 10 kg per tray","th":"40 กก. ถาดละ 10 กก."}},{"label":{"en":"Tray size","th":"ขนาดถาด"},"value":{"en":"41 × 50 cm","th":"41 × 50 ซม."}},{"label":{"en":"Tray heights, top to bottom","th":"ความสูงถาด จากบนลงล่าง"},"value":{"en":"23 / 20 / 20 / 18 cm","th":"23 / 20 / 20 / 18 ซม."}},{"label":{"en":"Tray sensor","th":"เซนเซอร์ถาด"},"value":{"en":"Infrared","th":"อินฟราเรด"}}]},{"title":{"en":"Battery","th":"แบตเตอรี่"},"rows":[{"label":{"en":"Battery life","th":"ระยะเวลาใช้งาน"},"value":{"en":"13 h, no load","th":"13 ชม. ไม่มีน้ำหนักบรรทุก"}},{"label":{"en":"Charging time","th":"เวลาชาร์จ"},"value":{"en":"4.5 h","th":"4.5 ชม."}},{"label":{"en":"Battery swap","th":"เปลี่ยนแบตเตอรี่"},"value":{"en":"Yes, quick swap","th":"ได้ เปลี่ยนได้รวดเร็ว"}}]},{"title":{"en":"Movement","th":"การเคลื่อนที่"},"rows":[{"label":{"en":"Speed","th":"ความเร็ว"},"value":{"en":"0.5–1.2 m/s, adjustable","th":"0.5–1.2 ม./วินาที ปรับได้"}},{"label":{"en":"Climbing angle","th":"ทางลาด"},"value":{"en":"Up to 5°","th":"สูงสุด 5°"}},{"label":{"en":"Suspension","th":"ระบบกันสะเทือน"},"value":{"en":"Automotive-grade independent suspension","th":"ระบบกันสะเทือนอิสระระดับยานยนต์"}}]},{"title":{"en":"Navigation and sensors","th":"การนำทางและเซนเซอร์"},"rows":[{"label":{"en":"Navigation","th":"การนำทาง"},"value":{"en":"LiDAR SLAM and visual SLAM","th":"LiDAR SLAM และ Visual SLAM"}},{"label":{"en":"Positioning","th":"การระบุตำแหน่ง"},"value":{"en":"Laser: no markers, any ceiling height. Markers: ceilings up to 8 m","th":"เลเซอร์: ไม่ต้องใช้มาร์กเกอร์ ไม่จำกัดความสูงเพดาน / มาร์กเกอร์: เพดานสูงไม่เกิน 8 ม."}},{"label":{"en":"Obstacle sensing","th":"การตรวจจับสิ่งกีดขวาง"},"value":{"en":"3 RGBD cameras + LiDAR","th":"กล้อง RGBD 3 ตัว + LiDAR"}},{"label":{"en":"Stopping response","th":"เวลาตอบสนองในการหยุด"},"value":{"en":"As short as 0.5 s","th":"เร็วสุด 0.5 วินาที"}}]},{"title":{"en":"Interaction and calling","th":"การโต้ตอบและการเรียกใช้งาน"},"rows":[{"label":{"en":"Interaction","th":"การโต้ตอบ"},"value":{"en":"Cat expressions, voice, status lights, touch response","th":"ใบหน้าแสดงอารมณ์แมว เสียง ไฟสถานะ ตอบสนองต่อการสัมผัส"}},{"label":{"en":"Calling","th":"การเรียกใช้งาน"},"value":{"en":"PUDU Link app, push-button caller, 4G watch (optional)","th":"แอป PUDU Link ปุ่มกดเรียก นาฬิกา 4G (ตัวเลือกเสริม)"}}]},{"title":{"en":"Size and weight","th":"ขนาดและน้ำหนัก"},"rows":[{"label":{"en":"Dimensions (L × W × H)","th":"ขนาด (ยาว × กว้าง × สูง)"},"value":{"en":"565 × 537 × 1,290 mm","th":"565 × 537 × 1,290 มม."}},{"label":{"en":"Weight","th":"น้ำหนัก"},"value":{"en":"55 kg","th":"55 กก."}},{"label":{"en":"Materials","th":"วัสดุ"},"value":{"en":"ABS and aircraft-grade aluminium alloy","th":"ABS และอะลูมิเนียมอัลลอยเกรดอากาศยาน"}}]}],"faqs":[{"question":{"en":"Do we need to put markers on the ceiling?","th":"ต้องติดมาร์กเกอร์บนเพดานหรือไม่"},"answer":{"en":"No. BellaBot can position itself by laser without markers. Markers are an alternative for venues with ceilings up to 8 m. We will advise which suits your venue.","th":"ไม่จำเป็น BellaBot ระบุตำแหน่งด้วยเลเซอร์ได้โดยไม่ต้องใช้มาร์กเกอร์ ส่วนมาร์กเกอร์เป็นอีกทางเลือกสำหรับสถานที่ที่เพดานสูงไม่เกิน 8 เมตร เราจะแนะนำวิธีที่เหมาะกับร้านของคุณ"}},{"question":{"en":"How much can it carry in one trip?","th":"ขนได้มากแค่ไหนต่อรอบ"},"answer":{"en":"Up to 40 kg across four trays, with up to 10 kg on each tray.","th":"ได้ถึง 40 กก. บน 4 ถาด ถาดละไม่เกิน 10 กก."}},{"question":{"en":"Can it go up a ramp?","th":"ขึ้นทางลาดได้หรือไม่"},"answer":{"en":"Yes, slopes of up to 5°. Steeper ramps and steps need another route.","th":"ได้ ทางลาดไม่เกิน 5° หากชันกว่านั้นหรือเป็นขั้นบันได ต้องใช้เส้นทางอื่น"}},{"question":{"en":"How long does the battery last?","th":"แบตเตอรี่ใช้งานได้นานเท่าไร"},"answer":{"en":"Up to 13 hours on a charge without a load, and 4.5 hours to recharge. The battery can be swapped for a charged one to keep it running.","th":"ใช้งานได้สูงสุด 13 ชั่วโมงต่อการชาร์จเมื่อไม่มีน้ำหนักบรรทุก และชาร์จเต็มใน 4.5 ชั่วโมง สามารถเปลี่ยนเป็นแบตเตอรี่ที่ชาร์จไว้แล้วเพื่อทำงานต่อได้ทันที"}}]}'::jsonb
where id = 'pudu-bella';

-- PuduBot 2
update public.products set
  name = 'PuduBot 2',
  brand = 'Pudu',
  category = 'delivery-robots',
  image_url = 'https://d5hk9n8my7l32.cloudfront.net/Pudu/PuduBot2/PuduBot2-cutout.webp',
  tagline = '{"en":"An all-round delivery robot that carries up to 40 kg, finds its way without markers and charges itself.","th":"หุ่นยนต์ส่งของอเนกประสงค์ บรรทุกได้ถึง 40 กก. นำทางได้โดยไม่ต้องติดมาร์กเกอร์ และกลับไปชาร์จเองได้"}'::jsonb,
  description = '{"en":"Pudu PuduBot 2 delivery robot in Thailand: up to 40 kg, 3 to 7 trays, marker-free navigation, dual LiDAR, automatic charging, maps up to 40,000 m². For restaurants, hotels, hospitals and offices. Get a quote from FindMyRobo.","th":"หุ่นยนต์ส่งของ Pudu PuduBot 2 ในประเทศไทย บรรทุกได้ถึง 40 กก. 3 ถึง 7 ถาด นำทางโดยไม่ต้องใช้มาร์กเกอร์ LiDAR คู่ ชาร์จอัตโนมัติ สร้างแผนที่ได้ถึง 40,000 ตร.ม. สำหรับร้านอาหาร โรงแรม โรงพยาบาล และสำนักงาน ขอใบเสนอราคาจาก FindMyRobo"}'::jsonb,
  features = '{"en":["Max load: 40 kg","Trays: 3 as standard, up to 7","Battery life: 12 h (no load)","Charging: automatic docking"],"th":["รับน้ำหนักสูงสุด: 40 กก.","ถาด: มาตรฐาน 3 ถาด สูงสุด 7 ถาด","แบตเตอรี่ใช้งานได้: 12 ชม. (ไม่มีน้ำหนักบรรทุก)","การชาร์จ: กลับแท่นชาร์จอัตโนมัติ"]}'::jsonb,
  page = '{"showcase":{"eyebrow":{"en":"Pudu · All-round delivery robot","th":"Pudu · หุ่นยนต์ส่งของอเนกประสงค์"},"heroImage":"https://d5hk9n8my7l32.cloudfront.net/Pudu/PuduBot2/PuduBot2-cutout.webp","figures":[{"value":"40 kg","label":{"en":"Max load","th":"รับน้ำหนักสูงสุด"}},{"value":"3–7","label":{"en":"Trays, 3 as standard","th":"ถาด มาตรฐาน 3 ถาด"}},{"value":"12 h","label":{"en":"Battery life, no load","th":"แบตเตอรี่ ไม่มีน้ำหนักบรรทุก"}},{"value":"40,000 m²","label":{"en":"Largest map","th":"พื้นที่แผนที่สูงสุด"}}]},"blocks":[{"type":"feature","eyebrow":{"en":"Navigation","th":"การนำทาง"},"heading":{"en":"No markers to put up.","th":"ไม่ต้องติดมาร์กเกอร์"},"body":{"en":"PUDU VSLAM+ finds its way by camera, so there are no ceiling markers to install. Pudu says this cuts setup time by 75%. It works under ceilings as high as 30 m.","th":"PUDU VSLAM+ นำทางด้วยกล้อง จึงไม่ต้องติดมาร์กเกอร์บนเพดาน Pudu ระบุว่าช่วยลดเวลาติดตั้งได้ 75% และใช้งานได้ใต้เพดานสูงถึง 30 เมตร"},"image":"/models/pudu/pudubot2/navigation.webp"},{"type":"feature","eyebrow":{"en":"Sensing","th":"การตรวจจับ"},"heading":{"en":"Two LiDARs, eyes all round.","th":"LiDAR คู่ มองเห็นรอบตัว"},"body":{"en":"Dual LiDAR gives 360° sensing, so PuduBot 2 sees its surroundings in every direction and moves through busy rooms more reliably and safely.","th":"LiDAR คู่ตรวจจับได้รอบทิศทาง 360° PuduBot 2 จึงรับรู้สภาพแวดล้อมได้ทุกด้าน และเคลื่อนที่ผ่านพื้นที่ที่มีคนพลุกพล่านได้อย่างมั่นใจและปลอดภัยยิ่งขึ้น"},"image":"/models/pudu/pudubot2/lidar.webp"},{"type":"feature","eyebrow":{"en":"Chassis","th":"แชสซี"},"heading":{"en":"Steady on every floor.","th":"มั่นคงบนพื้นทุกแบบ"},"body":{"en":"The chassis adapts to different floor surfaces, and Pudu rates it 30% more stable on the move. The body is fully enclosed.","th":"แชสซีปรับตัวเข้ากับพื้นผิวหลายแบบ Pudu ระบุว่าเคลื่อนที่ได้มั่นคงขึ้น 30% และตัวเครื่องเป็นแบบปิดมิดชิด"},"image":"/models/pudu/pudubot2/chassis.webp"},{"type":"feature","eyebrow":{"en":"Modes","th":"โหมดการทำงาน"},"heading":{"en":"More than delivery.","th":"ทำได้มากกว่าส่งอาหาร"},"body":{"en":"Switch between Delivery, Birthday, Cruise and Dish Return modes: from serving dishes and surprising a guest on their birthday to roaming the room and bringing empty plates back.","th":"สลับใช้โหมดส่งอาหาร โหมดวันเกิด โหมดเดินรอบร้าน และโหมดเก็บจาน ตั้งแต่เสิร์ฟอาหาร เซอร์ไพรส์วันเกิดลูกค้า เดินรอบร้าน ไปจนถึงเก็บจานเปล่ากลับครัว"},"image":"/models/pudu/pudubot2/restaurant.webp"},{"type":"feature","eyebrow":{"en":"Large venues","th":"พื้นที่ขนาดใหญ่"},"heading":{"en":"Big spaces, semi-outdoor too.","th":"พื้นที่กว้าง หรือกึ่งกลางแจ้งก็ได้"},"body":{"en":"It maps spaces of up to 40,000 m² and gets around better in semi-outdoor areas, so it suits restaurants, hotels, hospitals, offices and shops. Accessories such as an enclosed cabinet are available.","th":"สร้างแผนที่ได้ถึง 40,000 ตร.ม. และเคลื่อนที่ในพื้นที่กึ่งกลางแจ้งได้ดีขึ้น จึงเหมาะกับร้านอาหาร โรงแรม โรงพยาบาล สำนักงาน และร้านค้า มีอุปกรณ์เสริม เช่น ตู้แบบปิด"},"image":"/models/pudu/pudubot2/outdoor.webp"},{"type":"feature","eyebrow":{"en":"Charging","th":"การชาร์จ"},"heading":{"en":"Charges itself.","th":"กลับไปชาร์จเองได้"},"body":{"en":"PuduBot 2 docks and recharges on its own, with no one needing to plug it in, so it is ready when it is called. It can also charge by cable. A full charge takes 4 hours.","th":"PuduBot 2 กลับเข้าแท่นและชาร์จได้เองโดยไม่ต้องมีคนเสียบสาย จึงพร้อมทำงานทุกครั้งที่ถูกเรียก ชาร์จผ่านสายได้เช่นกัน ชาร์จเต็มใน 4 ชั่วโมง"},"image":"/models/pudu/pudubot2/charging.webp"},{"type":"feature","eyebrow":{"en":"Calling","th":"การเรียกใช้งาน"},"heading":{"en":"One tap to send it.","th":"สั่งงานได้ในคลิกเดียว"},"body":{"en":"Staff assign and manage tasks from a Pudu Watch, the Pudu Pager or the PUDU Link app. Calling devices are optional: ask us what is included.","th":"พนักงานสั่งงานและจัดการได้จากนาฬิกา Pudu Watch เพจเจอร์ Pudu Pager หรือแอป PUDU Link อุปกรณ์เรียกเป็นตัวเลือกเสริม สอบถามเราได้ว่ามีอะไรรวมอยู่บ้าง"}},{"type":"feature","eyebrow":{"en":"Platform","th":"แพลตฟอร์ม"},"heading":{"en":"Room to grow.","th":"พร้อมต่อยอด"},"body":{"en":"PUDU OS supports third-party development and customisation, and PuduBot 2 connects by Type-C, 4G, LoRa and Wi-Fi.","th":"PUDU OS รองรับการพัฒนาต่อยอดและปรับแต่งโดยบุคคลที่สาม และ PuduBot 2 เชื่อมต่อได้ทั้ง Type-C, 4G, LoRa และ Wi-Fi"}}],"specGroups":[{"title":{"en":"Trays and load","th":"ถาดและน้ำหนักบรรทุก"},"rows":[{"label":{"en":"Trays","th":"จำนวนถาด"},"value":{"en":"3 as standard, up to 7","th":"มาตรฐาน 3 ถาด สูงสุด 7 ถาด"}},{"label":{"en":"Tray size","th":"ขนาดถาด"},"value":{"en":"52 × 43.2 cm","th":"52 × 43.2 ซม."}},{"label":{"en":"Max load","th":"รับน้ำหนักสูงสุด"},"value":{"en":"40 kg","th":"40 กก."}}]},{"title":{"en":"Battery and charging","th":"แบตเตอรี่และการชาร์จ"},"rows":[{"label":{"en":"Battery life","th":"ระยะเวลาใช้งาน"},"value":{"en":"12 h, no load","th":"12 ชม. ไม่มีน้ำหนักบรรทุก"}},{"label":{"en":"Charging time","th":"เวลาชาร์จ"},"value":{"en":"4 h","th":"4 ชม."}},{"label":{"en":"Charging","th":"วิธีชาร์จ"},"value":{"en":"Automatic docking or cable","th":"กลับแท่นชาร์จอัตโนมัติ หรือชาร์จผ่านสาย"}}]},{"title":{"en":"Movement","th":"การเคลื่อนที่"},"rows":[{"label":{"en":"Speed","th":"ความเร็ว"},"value":{"en":"0.5–1.2 m/s","th":"0.5–1.2 ม./วินาที"}},{"label":{"en":"Narrowest path","th":"ทางเดินแคบสุด"},"value":{"en":"80 cm","th":"80 ซม."}}]},{"title":{"en":"Navigation and sensors","th":"การนำทางและเซนเซอร์"},"rows":[{"label":{"en":"Navigation","th":"การนำทาง"},"value":{"en":"PUDU VSLAM+, no markers","th":"PUDU VSLAM+ ไม่ต้องใช้มาร์กเกอร์"}},{"label":{"en":"Max ceiling height","th":"ความสูงเพดานสูงสุด"},"value":{"en":"30 m","th":"30 ม."}},{"label":{"en":"Max mapping area","th":"พื้นที่แผนที่สูงสุด"},"value":{"en":"40,000 m²","th":"40,000 ตร.ม."}},{"label":{"en":"Sensing","th":"การตรวจจับ"},"value":{"en":"Dual LiDAR, 360°","th":"LiDAR คู่ รอบทิศทาง 360°"}}]},{"title":{"en":"Modes and calling","th":"โหมดและการเรียกใช้งาน"},"rows":[{"label":{"en":"Modes","th":"โหมด"},"value":{"en":"Delivery, Birthday, Cruise, Dish Return","th":"ส่งอาหาร วันเกิด เดินรอบร้าน เก็บจาน"}},{"label":{"en":"Calling","th":"การเรียกใช้งาน"},"value":{"en":"Pudu Watch, Pudu Pager, PUDU Link app (optional)","th":"Pudu Watch, Pudu Pager, แอป PUDU Link (ตัวเลือกเสริม)"}}]},{"title":{"en":"Connectivity","th":"การเชื่อมต่อ"},"rows":[{"label":{"en":"Connections","th":"ช่องทางเชื่อมต่อ"},"value":{"en":"Type-C, 4G, LoRa, Wi-Fi","th":"Type-C, 4G, LoRa, Wi-Fi"}},{"label":{"en":"Platform","th":"แพลตฟอร์ม"},"value":{"en":"PUDU OS, open to third-party development","th":"PUDU OS รองรับการพัฒนาโดยบุคคลที่สาม"}}]},{"title":{"en":"Size and weight","th":"ขนาดและน้ำหนัก"},"rows":[{"label":{"en":"Dimensions (L × W × H)","th":"ขนาด (ยาว × กว้าง × สูง)"},"value":{"en":"580 × 535 × 1,290 mm","th":"580 × 535 × 1,290 มม."}},{"label":{"en":"Weight","th":"น้ำหนัก"},"value":{"en":"39 kg","th":"39 กก."}}]}],"faqs":[{"question":{"en":"Do we need to put markers on the ceiling?","th":"ต้องติดมาร์กเกอร์บนเพดานหรือไม่"},"answer":{"en":"No. PuduBot 2 navigates by camera with PUDU VSLAM+, under ceilings up to 30 m high.","th":"ไม่ต้อง PuduBot 2 นำทางด้วยกล้องผ่าน PUDU VSLAM+ ใช้งานได้ใต้เพดานสูงถึง 30 เมตร"}},{"question":{"en":"How narrow a space can it pass?","th":"ผ่านทางแคบได้แค่ไหน"},"answer":{"en":"It needs a path at least 80 cm wide.","th":"ต้องมีทางเดินกว้างอย่างน้อย 80 ซม."}},{"question":{"en":"How many trays does it have?","th":"มีกี่ถาด"},"answer":{"en":"Three as standard, and up to seven. It carries up to 40 kg in total.","th":"มาตรฐาน 3 ถาด เพิ่มได้สูงสุด 7 ถาด และบรรทุกรวมได้ถึง 40 กก."}},{"question":{"en":"Does someone need to charge it?","th":"ต้องมีคนคอยชาร์จหรือไม่"},"answer":{"en":"No. It returns to its dock and charges itself; a full charge takes 4 hours, and it runs up to 12 hours on a charge without a load.","th":"ไม่ต้อง หุ่นยนต์กลับแท่นและชาร์จเองได้ ชาร์จเต็มใน 4 ชั่วโมง และใช้งานได้สูงสุด 12 ชั่วโมงต่อการชาร์จเมื่อไม่มีน้ำหนักบรรทุก"}}]}'::jsonb
where id = 'pudu-2';

commit;

